details.returned_prompt:
{
  "high_level_description": "An editorial outdoor photograph of a one-person wild camp on a windswept fell above a northern English lake in late afternoon, with a small dome tent, kettle steaming on a stone, and distant fells receding toward a still lake, shot on 35mm equivalent with fine Kodak Portra grain.",
  "compositional_deconstruction": {
    "background": "A windswept northern English fell in late afternoon under clearing overcast daylight, cool-leaning neutral white balance. Distant fells layer across the lower third in soft blue-green haze, receding toward a still lake at the bottom of the valley. A single low sun rakes from the right edge, catching grass tips and steam. Heather-covered slope fills the foreground in mossy greens and heather purple-brown, dotted with low grasses and scattered stones. Slight breeze visible in the grass tips. Palette of mossy greens, heather purple-brown, slate grey, with warm cream as the only saturated note.",
    "elements": [
      {
        "type": "obj",
        "desc": "Compact one-person dome tent, midground left-of-center, anchored to the peat with taut guy lines staked into the ground. Rainfly slightly damp from earlier drizzle, rim catching low sun from the right. Entrance flap rolled back revealing a glimpse of dark interior. Slate-grey body with subtle sheen."
      },
      {
        "type": "obj",
        "desc": "Compressed down sleeping bag in slate-grey and charcoal laid out on the ground beside the tent, partially unzipped showing a darker inner lining. Muted olive sleeping mat beneath it, edges slightly rumpled."
      },
      {
        "type": "obj",
        "desc": "Small portable camp stove set up on a flat grey stone just outside the tent in the foreground right. Battered enamel kettle perched on top with chipped white enamel and dark rim, thin curl of steam rising from the spout catching the low sun."
      },
      {
        "type": "obj",
        "desc": "Enamel mug of tea steaming beside the stove on the flat stone, cream-colored exterior with a faint ring of condensation on the rock beneath it. Thin wisp of steam curling upward, the only saturated warm note in the frame."
      },
      {
        "type": "obj",
        "desc": "Folded wool blanket in muted earth tones and a small canvas rucksack in faded olive resting against a weathered grey boulder near the tent. Rucksack straps loose, blanket neatly folded."
      },
      {
        "type": "obj",
        "desc": "Tuft of heather and low grass cropped close to the lens in the foreground left, blades catching the low sun from the right, slight motion blur from the breeze."
      }
    ]
  }
}
